class Base {
    public:
        virtual ReturnType FunctionName(Parameters); // Declaration of a virtual function
};

class Derived : public Base {
    public:
        ReturnType FunctionName(Parameters) override; // Override in derived class
};

code_example:
#include <iostream>

class ErrorCategory {
public:
    virtual void display() const {
        std::cout << "Base ErrorCategory" << std::endl;
    }
    virtual ~ErrorCategory() = default; // Virtual destructor for proper cleanup
};

class SystemErrorCategory : public ErrorCategory {
public:
    void display() const override {
        std::cout << "System Error Category" << std::endl;
    }
};

int main() {
    const ErrorCategory& category1 = SystemErrorCategory();
    category1.display(); // Calls SystemErrorCategory::display() due to virtual dispatch
    return 0;
}
